#!/usr/bin/env python3
"""마음냥 정원 v51: 추억 카드 수집·교환·진열 서버 업데이트.
Default: review only. --deploy: update gardenApi, retaining test premium access.
"""
import argparse, base64, hashlib, json, os, shutil, subprocess, sys, tempfile, zipfile, zlib
from pathlib import Path
PROJECT='mycatapp-99bc8'
REGION='asia-northeast3'
FUNCTION='gardenApi'
BASELINE_INDICES=['091d73e8eb7d9305e0540607b859a6480ac2c349a20fda562a2d2aefb8860a5a', '994590a662d9763b9bb1b2fc30d7445ee6a634de4faadb5898c228ac742bae67', '8af45538a828bce55c89c1baee51bdf7dda6f15d802d1ff9222dd5df166b5836', '9f5f4c995849e42e154844ebd366d6c3cb5da55251a85abf92f7ba8ac63d7da3']
BASELINE_VILLAGE='006d98b2cbd4a69436c73ba171da20b15fab22d3f539a394e44ef1f9ca2bfe65'
PAYLOAD={'index.js': '', 'cat-visits.js': '', 'orchard.js': '', 'premium-test-access.js': '', 'memory-cards.js': ''}
def sha(raw): return hashlib.sha256(raw).hexdigest()
REVIEWED_DEPLOYED_INDEX = 'dddcdc4e6e548c224133246c6a7ef2c38e818f3a191b7a257f1955de5be381d4'
REVIEWED_PATCHED_INDEX = '3a623e45ce823b3794f8d3848b23485d97b77e1b707320a2a8ea8759658d5277'
def desired_payload(root):
    new = {n: zlib.decompress(base64.b64decode(s)) for n,s in PAYLOAD.items()}
    # Keep this deployment's existing function export layout. gardenApi does
    # not need the separately deployed socialAuth entry point imported here.
    if sha((root/'index.js').read_bytes()) in (REVIEWED_DEPLOYED_INDEX, REVIEWED_PATCHED_INDEX):
        new['index.js'] = new['index.js'].replace(b"export { socialAuth } from './social-auth.js';\n", b'')
    return new

def check_source(root):
    if not (root/'index.js').is_file() or not (root/'garden-village.js').is_file():
        raise RuntimeError('Expected backend files are absent. Nothing deployed.')
    new = desired_payload(root)
    if sha((root/'garden-village.js').read_bytes()) != BASELINE_VILLAGE:
        raise RuntimeError('Deployed garden-village.js differs from reviewed baseline. Nothing deployed.')
    if all((root/n).is_file() and (root/n).read_bytes()==raw for n,raw in new.items()): return False
    if sha((root/'index.js').read_bytes()) not in [*BASELINE_INDICES, REVIEWED_DEPLOYED_INDEX]:
        raise RuntimeError('Deployed index.js differs from reviewed v47-v50 or uploaded server baseline. Nothing deployed. Review before merging.')
    for name in ['cat-visits.js','orchard.js','premium-test-access.js','memory-cards.js']:
        if (root/name).exists() and (root/name).read_bytes()!=new[name]:
            raise RuntimeError('Unrecognized deployed '+name+'. Nothing deployed.')
    return new

def extract_safely(archive, target):
    with zipfile.ZipFile(archive) as z:
        for info in z.infolist():
            p=Path(info.filename)
            if p.is_absolute() or '..' in p.parts or (info.external_attr >> 16) & 0o170000 == 0o120000:
                raise RuntimeError('Unsafe source archive. Nothing deployed.')
        z.extractall(target)

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--deploy', action='store_true', help='Deploy the verified source patch to existing gardenApi')
    args=parser.parse_args()
    os.umask(0o077)
    for cmd in ['gcloud','node']:
        if not shutil.which(cmd): raise RuntimeError(cmd+' is required; run this in Google Cloud Shell.')
    flags=['--project='+PROJECT,'--region='+REGION,'--gen2']
    def describe():
        return json.loads(subprocess.check_output(['gcloud','functions','describe',FUNCTION,*flags,'--format=json'],text=True))
    meta=describe();build=meta.get('buildConfig',{});storage=build.get('source',{}).get('storageSource',{})
    if meta.get('environment')!='GEN_2' or build.get('entryPoint')!=FUNCTION or not storage.get('bucket') or not storage.get('object'):
        raise RuntimeError('Existing function identity/source could not be verified. Nothing deployed.')
    runtime=build.get('runtime','')
    if runtime!='nodejs22': raise RuntimeError('Expected existing Node.js 22 runtime. Nothing deployed.')
    work=Path(tempfile.mkdtemp(prefix='mindnyang-v51-',dir=Path.home()))
    archive=work/'original-source.zip';original=work/'original';patched=work/'patched'
    uri='gs://'+storage['bucket']+'/'+storage['object']
    if storage.get('generation'): uri+='#'+str(storage['generation'])
    subprocess.run(['gcloud','storage','cp',uri,str(archive),'--quiet'],check=True)
    extract_safely(archive,original)
    roots=[p.parent for p in original.rglob('index.js') if (p.parent/'garden-village.js').is_file()]
    if len(roots)!=1: raise RuntimeError('Cannot identify one backend source root. Nothing deployed.')
    root=roots[0];patch=check_source(root)
    if patch is False:
        if meta.get('serviceConfig',{}).get('environmentVariables',{}).get('PREMIUM_TEST_ACCESS')=='true':
            print('v51 test server is already enabled. No deployment needed.');return
        patch=desired_payload(root)
    shutil.copytree(root,patched)
    for name,raw in patch.items(): (patched/name).write_bytes(raw)
    for name in patch: subprocess.run(['node','--check',str(patched/name)],check=True)
    # Default gcloud ignore handling preserves the original project configuration.
    deploy=['gcloud','functions','deploy',FUNCTION,*flags,'--runtime='+runtime,'--entry-point='+FUNCTION,'--source='+str(patched),'--update-env-vars=PREMIUM_TEST_ACCESS=true','--quiet']
    old_test=meta.get('serviceConfig',{}).get('environmentVariables',{}).get('PREMIUM_TEST_ACCESS')
    if old_test not in (None,'true','false'): raise RuntimeError('Unrecognized existing test setting. Nothing deployed.')
    rollback=[*deploy]
    rollback[rollback.index('--update-env-vars=PREMIUM_TEST_ACCESS=true')]='--remove-env-vars=PREMIUM_TEST_ACCESS' if old_test is None else '--update-env-vars=PREMIUM_TEST_ACCESS='+old_test
    rollback[rollback.index('--source='+str(patched))]='--source='+str(root)
    import shlex
    (work/'ROLLBACK.txt').write_text(shlex.join(rollback)+'\n')
    print('Verified patch ready:',patched)
    print('Original source and rollback command:',work)
    print('Updates the reviewed feature modules and enables PREMIUM_TEST_ACCESS=true. Existing secrets, IAM and other environment variables are retained.')
    if not args.deploy:
        print('Review these files; rerun this script with --deploy to apply.');return
    # Abort if another deployment happened while downloading/preparing.
    current=describe()
    if current.get('updateTime')!=meta.get('updateTime') or current.get('buildConfig',{}).get('source')!=build.get('source'):
        raise RuntimeError('Function changed during preparation. Nothing deployed; retry after review.')
    subprocess.run(deploy,check=True)
    after=describe()
    if after.get('state')!='ACTIVE' or after.get('serviceConfig',{}).get('environmentVariables',{}).get('PREMIUM_TEST_ACCESS')!='true': raise RuntimeError('Deployment did not report ACTIVE. Inspect Cloud Console; backup retained.')
    print('Deployment is ACTIVE. Test card collection, duplicate trade acceptance/cancellation, showcases and coloring rewards with two neighbor accounts in the v51 app.')

if __name__=='__main__':
    try: main()
    except (RuntimeError,subprocess.CalledProcessError) as e:
        print('Stopped:',str(e),file=sys.stderr);sys.exit(1)
